<?php $items = kimpu_homepage_page_children( 'kimpu_services_source_page', absint( get_theme_mod( 'kimpu_services_limit', 6 ) ) ); ?><section class="section <?php echo esc_attr( kimpu_homepage_section_classes( 'services' ) ); ?>" id="services"><div class="container"><?php kimpu_homepage_section_header( 'services' ); ?><?php if ( $items ) : ?><div class="homepage-card-grid homepage-columns-<?php echo esc_attr( absint( get_theme_mod( 'kimpu_services_columns', 3 ) ) ); ?>"><?php foreach ( $items as $item ) : ?><article class="content-card service-card"><?php if ( has_post_thumbnail( $item->ID ) ) { echo get_the_post_thumbnail( $item->ID, 'medium_large', array( 'alt' => esc_attr( get_post_meta( get_post_thumbnail_id( $item->ID ), '_wp_attachment_image_alt', true ) ) ) ); } ?><div class="content-card-body"><h3><?php echo esc_html( $item->post_title ); ?></h3><p><?php echo esc_html( wp_trim_words( wp_strip_all_tags( $item->post_content ), 24 ) ); ?></p><a class="text-link" href="<?php echo esc_url( get_permalink( $item->ID ) ); ?>"><?php esc_html_e( 'Read more', 'kimpu-multipurpose' ); ?> →</a></div></article><?php endforeach; ?></div><?php else : ?><p class="empty-state"><?php esc_html_e( 'Select a parent page with published child pages to show services.', 'kimpu-multipurpose' ); ?></p><?php endif; ?></div></section>
